-- 5CL1 字詞理解與運用：新增 60 題（由 20 題擴充至 80 題）
-- 可安全重複執行：以 node_id + question_text 跳過已存在題目。
-- 執行前不會刪除或改寫原有題目。

begin;

do $$
begin
  if not exists (select 1 from public.curriculum_nodes where code = '5CL1') then
    raise exception '找不到課程單元 5CL1，請先建立課程結構。';
  end if;
end $$;

create temporary table tmp_5cl1_expansion (
  category text not null,
  question_text text not null,
  options jsonb not null,
  correct_answer jsonb not null,
  explanation text not null,
  hint text not null,
  difficulty integer not null
) on commit drop;


do $$
begin
  if (select count(*) from tmp_5cl1_expansion) <> 60 then
    raise exception '5CL1 增補題數不是 60 題。';
  end if;
  if (select count(distinct question_text) from tmp_5cl1_expansion) <> 60 then
    raise exception '5CL1 增補題目中有重複題幹。';
  end if;
end $$;

with target_node as (
  select id from public.curriculum_nodes where code = '5CL1' limit 1
)
select
  n.id, 'multiple_choice', t.question_text, t.options, t.difficulty, 'teacher', 'published'
from tmp_5cl1_expansion t
cross join target_node n
where not exists (
  select 1 from public.questions q
  where q.node_id = n.id and q.question_text = t.question_text
);

with target_node as (
  select id from public.curriculum_nodes where code = '5CL1' limit 1
)
select q.id, t.correct_answer, t.explanation, t.hint
from tmp_5cl1_expansion t
cross join target_node n
join public.questions q on q.node_id = n.id and q.question_text = t.question_text
on conflict (question_id) do update set
  correct_answer = excluded.correct_answer,
  explanation = excluded.explanation,
  hint = excluded.hint;

commit;

select
  n.code,
  n.title_zh,
  count(q.id) filter (where q.status = 'published') as published_questions
from public.curriculum_nodes n
left join public.questions q on q.node_id = n.id
where n.code = '5CL1'
group by n.code, n.title_zh;
